<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';
$error=null;$user=[];$p=bi_step22_period($_GET['month']??null);$report=(string)($_GET['report']??'summary');$format=(string)($_GET['format']??'html');$allowed=['summary','trends','products','customers','suppliers','signals','targets'];if(!in_array($report,$allowed,true))$report='summary';
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.export');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];$m=bi_step22_metrics($pdo,$orgId,$p['start'],$p['end']);$rows=[];$headers=[];
if($report==='summary'){$headers=['Metric','Value','Scope'];foreach(['sales_count'=>'Sales Count','sales_revenue'=>'Sales Revenue','sales_vp'=>'Sales VP','verified_profit'=>'Verified Profit','profit_deferred_sales'=>'Deferred-Cost Sales','collections'=>'Collections','purchase_spend'=>'Purchase Spend','new_leads'=>'New Leads','lead_conversions'=>'Lead Conversions','finance_income'=>'Finance Income','finance_expense'=>'Finance Expense','finance_net'=>'Finance Net','customer_receivable'=>'Customer Receivable','supplier_payable'=>'Supplier Payable','inventory_units'=>'Sellable Inventory Units','inventory_value_known'=>'Known Inventory Value'] as $k=>$label)$rows[]=[$label,$m[$k]??0,in_array($k,['customer_receivable','supplier_payable','inventory_units','inventory_value_known'],true)?'Current exposure':$p['label']];}
elseif($report==='trends'){$headers=['Month','Sales','Revenue','VP','Verified Profit','Deferred Cost Sales','Collections','Purchases','New Leads','Conversions','Finance Net'];foreach(bi_step22_monthly_trends($pdo,$orgId,12) as $r)$rows[]=[$r['label'],$r['sales_count'],$r['sales_revenue'],$r['sales_vp'],$r['verified_profit'],$r['profit_deferred_sales'],$r['collections'],$r['purchase_spend'],$r['new_leads'],$r['lead_conversions'],$r['finance_net']];}
elseif($report==='products'){$headers=['Stock No.','Product','Qty','Revenue','VP','Verified Profit','Costed Lines','Total Lines'];foreach(bi_step22_top_products($pdo,$orgId,$p['start'],$p['end'],50) as $r)$rows[]=[$r['stock_no'],$r['product_name_snapshot'],$r['qty'],$r['revenue'],$r['vp'],$r['verified_profit'],$r['costed_lines'],$r['lines']];}
elseif($report==='customers'){$headers=['Customer','Orders','Revenue','Collected','Receivable'];foreach(bi_step22_top_customers($pdo,$orgId,$p['start'],$p['end'],50) as $r)$rows[]=[$r['customer_name'],$r['orders'],$r['revenue'],$r['collected'],$r['receivable']];}
elseif($report==='suppliers'){$headers=['Supplier','Bills','Billed','Paid','Outstanding'];foreach(bi_step22_top_suppliers($pdo,$orgId,$p['start'],$p['end'],50) as $r)$rows[]=[$r['supplier_name'],$r['bills'],$r['billed'],$r['paid'],$r['outstanding']];}
elseif($report==='signals'){$headers=['Signal','Type','Severity','Detail','Workflow Status'];foreach(bi_step22_signals($pdo,$orgId,$m) as $r)$rows[]=[$r['title'],$r['type'],$r['severity'],$r['detail'],$r['workflow_status']];}
else{$headers=['Code','Target','Metric','Period Start','Period End','Target Value','Actual','Achievement %','Status'];foreach(bi_step22_targets($pdo,$orgId,$p['start'],$p['end'],$m) as $r)$rows[]=[$r['target_code'],$r['target_name'],$r['metric_name'],$r['period_start'],$r['period_end'],$r['target_value'],$r['actual_value'],$r['achievement_pct'],$r['status']];}
if($format==='csv'){bi_step22_log_export($pdo,$orgId,$report,$p['start'],$p['end'],count($rows),(int)$user['id']);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="HWC-BI-'.$report.'-'.$p['key'].'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,$headers);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}
}catch(Throwable $e){$error=$e->getMessage();$rows=[];$headers=[];}
