href="?month=<?=rawurlencode($p['key'])?>&report=<?=rawurlencode($report)?>&format=csv">Download CSV</a><button class="os-btn" type="button" onclick="window.print()">Print / Save PDF</button></form></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2><?=bi_step22_h(ucwords($report))?> • <?=bi_step22_h($p['label'])?></h2><p><?=count($rows)?> row(s).</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><?php foreach($headers as $h):?><th><?=bi_step22_h($h)?></th><?php endforeach;?></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="<?=max(1,count($headers))?>">No rows in this report.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=bi_step22_h($v===null?'N/A':$v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></body></html>